    const article = document.querySelector('article');
    if (!article) return null;
    const text = article.innerText || article.textContent;
    // search for equine veterinarian
    const regex = /equine veterinarian/i;
    const match = text.match(regex);
    if (match) {
        // find the surrounding context
        const index = text.indexOf(match[0]);
        const start = Math.max(0, index - 200);
        const end = Math.min(text.length, index + 200);
        return text.substring(start, end);
    }
    // if not found, search for veterinarian
    const vetRegex = /veterinarian/i;
    const vetMatch = text.match(vetRegex);
    if (vetMatch) {
        const idx = text.indexOf(vetMatch[0]);
        const start = Math.max(0, idx - 200);
        const end = Math.min(text.length, idx + 200);
        return 'Found veterinarian: ' + text.substring(start, end);
    }
    return 'Not found';
}"}

